// Only well-formed A1 callbacks reach the database; anything else is ignored.
const query = $input.first().json.callback_query;
const match = /^a1:([AGR]):([0-9a-f]{32})$/.exec(query?.data ?? '');
if (!query || !match) return [];
const actions = { A: 'APPROVE', G: 'REGENERATE', R: 'REJECT' };
return [{
  json: {
    queryId: query.id,
    userId: String(query.from.id),
    chatId: String(query.message?.chat?.id ?? ''),
    messageId: String(query.message?.message_id ?? ''),
    originalText: String(query.message?.text ?? ''),
    action: actions[match[1]],
    token: match[2],
  },
}];

// approval_telegram_decide() result codes -> short replies. Buttons are removed once the request
// is settled (decided, superseded, expired); a refused stranger leaves the message untouched.
const input = $('Parse callback').first().json;
const { result, version } = $input.first().json;
const done = { APPROVE: 'Approved', REJECT: 'Rejected (video cancelled)', REGENERATE: `Regenerating as v${version}` };
const replies = {
  OK: done[input.action],
  NOT_ALLOWED: 'You are not an approver.',
  NOT_FOUND: 'Unknown approval.',
  NOT_PENDING: 'Already decided.',
  EXPIRED: 'This request expired.',
  SUPERSEDED: 'A newer version exists; this request is no longer valid.',
  HASH_MISMATCH: 'The script changed after this request; wait for the new request.',
};
const settled = ['OK', 'NOT_PENDING', 'EXPIRED', 'SUPERSEDED'].includes(result);
const decidedAt = new Date().toISOString().replace('T', ' ').slice(0, 16);
return [{
  json: {
    answer: replies[result] ?? `Not applied (${result}).`,
    settled,
    chatId: input.chatId,
    messageId: input.messageId,
    queryId: input.queryId,
    editedText: `${input.originalText}\n\n${result === 'OK' ? 'Decision' : 'Closed'}: ${replies[result] ?? result} (${decidedAt} UTC)`.slice(0, 4096),
  },
}];
